import numpy as np
from scipy import ndimage
d = np.load('source_pixels.npz')['rgb'].astype(int)
# precise per-frame centroids
def blobs(m, minsz):
    lab,n=ndimage.label(m)
    out=[]
    for i in range(1,n+1):
        yy,xx=np.where(lab==i)
        if len(xx)>=minsz: out.append((xx.mean(),yy.mean(),len(xx)))
    return out
def track(kind, t0):
    pts=[]; pred=None
    for t in range(96):
        f=d[t]; r,g,b=[f[:,:,i] for i in range(3)]
        m=(r>185)&(g>185)&(b>185) if kind=='w' else (r<70)&(g<70)&(b<70)
        cand=[c for c in blobs(m,5) if 35<c[1]<110 and 30<c[0]<230]
        tgt=pred if pred else t0
        if cand:
            c=min(cand,key=lambda c:(c[0]-tgt[0])**2+(c[1]-tgt[1])**2)
            pts.append((c[0],c[1])); pred=(c[0],c[1])
        else: pts.append(None)
    return pts
w=track('w',(85,93)); k=track('k',(128,71))
print('white:')
for t in range(0,22): print(t, None if w[t] is None else tuple(round(v,2) for v in w[t]))
print('black:')
for t in range(10,96,2): print(t, None if k[t] is None else tuple(round(v,2) for v in k[t]))
\""
